def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    arms = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # find every cell whose four orthogonal neighbours share its (non-background) colour
    centres = []
    for y in range(1, H - 1):
        for x in range(1, W - 1):
            c = g[y, x]
            if c != bg and all(g[y + dy, x + dx] == c for dy, dx in arms):
                centres.append((y, x))

    # stamp each plus with colour 8, one stage per plus
    for y, x in centres:
        for dy, dx in [(0, 0)] + arms:
            out[y + dy, x + dx] = 8
        emit(out, f"Cell ({y},{x}) has all four orthogonal neighbours in its colour, so it is the centre of a plus; recolour the centre and its four arms to 8")

    emit(out, "All plus signs recoloured; everything else unchanged")
    return out
